const { World, Before, After, setWorldConstructor } = require('@cucumber/cucumber');
const { Window } = require('happy-dom');
const fs = require('fs');
const path = require('path');

class AppWorld extends World {
  constructor(options) {
    super(options);
    this.window = null;
    this.document = null;
    this.localStorage = null;
  }

  loadApp() {
    const htmlPath = path.resolve(__dirname, '../../assets/app-template.index.html');
    let html = fs.readFileSync(htmlPath, 'utf8');

    // Fix paths for test environment
    html = html.replace('node_modules/todomvc-common/base.css', '../../node_modules/todomvc-common/base.css');
    html = html.replace('node_modules/todomvc-app-css/index.css', '../../node_modules/todomvc-app-css/index.css');
    html = html.replace('css/app.css', '../../css/app.css');
    html = html.replace('node_modules/todomvc-common/base.js', '../../node_modules/todomvc-common/base.js');
    html = html.replace('js/app.js', '../../js/app.js');

    this.window = new Window({
      url: 'http://localhost',
      contentType: 'text/html',
    });
    this.document = this.window.document;
    this.localStorage = this.window.localStorage;

    // Write HTML to window
    this.document.open();
    this.document.write(html);
    this.document.close();

    // Load the app script
    const appPath = path.resolve(__dirname, '../../js/app.js');
    if (fs.existsSync(appPath)) {
      const appScript = fs.readFileSync(appPath, 'utf8');
      const scriptEl = this.document.createElement('script');
      scriptEl.textContent = appScript;
      this.document.body.appendChild(scriptEl);
    }
  }

  createElement(tag, attrs = {}) {
    const el = this.document.createElement(tag);
    for (const [key, value] of Object.entries(attrs)) {
      el.setAttribute(key, value);
    }
    return el;
  }

  querySelector(selector) {
    return this.document.querySelector(selector);
  }

  querySelectorAll(selector) {
    return this.document.querySelectorAll(selector);
  }
}

setWorldConstructor(AppWorld);

const { Given, When, Then } = require('@cucumber/cucumber');
const { expect } = require('chai');

// Background
Given('the app is loaded', function () {
  this.loadApp();
});

// Adding todos
Given('the new-todo input is focused', function () {
  const input = this.querySelector('.new-todo');
  input.focus();
});

When('the user types {string} and presses Enter', function (text) {
  const input = this.querySelector('.new-todo');
  input.value = text;
  input.dispatchEvent(new this.window.KeyboardEvent('keydown', { key: 'Enter', keyCode: 13 }));
});

Then('the todo list contains {int} item(s)', function (count) {
  const items = this.querySelectorAll('.todo-list li');
  expect(items.length).to.equal(count);
});

Then('the first todo has title {string} and is not completed', function (title) {
  const firstTodo = this.querySelector('.todo-list li');
  expect(firstTodo).to.not.be.null;
  const label = firstTodo.querySelector('label');
  expect(label.textContent).to.equal(title);
  expect(firstTodo.classList.contains('completed')).to.be.false;
});

Then('the new-todo input is empty', function () {
  const input = this.querySelector('.new-todo');
  expect(input.value).to.equal('');
});

// Completing todos
Given('a todo {string}', function (title) {
  const input = this.querySelector('.new-todo');
  input.value = title;
  input.dispatchEvent(new this.window.KeyboardEvent('keydown', { key: 'Enter', keyCode: 13 }));
});

Given('a completed todo {string}', function (title) {
  const input = this.querySelector('.new-todo');
  input.value = title;
  input.dispatchEvent(new this.window.KeyboardEvent('keydown', { key: 'Enter', keyCode: 13 }));
  const checkbox = this.querySelector('.todo-list li:first-child .toggle');
  checkbox.click();
});

When('the user toggles the first todo checkbox', function () {
  const checkbox = this.querySelector('.todo-list li:first-child .toggle');
  checkbox.click();
});

When('the user toggles the second todo checkbox', function () {
  const checkbox = this.querySelector('.todo-list li:nth-child(2) .toggle');
  checkbox.click();
});

Then('the first todo has title {string} and is completed', function (title) {
  const firstTodo = this.querySelector('.todo-list li');
  expect(firstTodo).to.not.be.null;
  const label = firstTodo.querySelector('label');
  expect(label.textContent).to.equal(title);
  expect(firstTodo.classList.contains('completed')).to.be.true;
});

Then('the first todo has class {string}', function (className) {
  const firstTodo = this.querySelector('.todo-list li');
  expect(firstTodo).to.not.be.null;
  expect(firstTodo.classList.contains(className)).to.be.true;
});

// Toggle all
When('the user toggles the toggle-all checkbox on', function () {
  const toggleAll = this.querySelector('#toggle-all');
  toggleAll.click();
});

Then('every todo is completed', function () {
  const items = this.querySelectorAll('.todo-list li');
  items.forEach(item => {
    expect(item.classList.contains('completed')).to.be.true;
  });
});

Then('every todo is not completed', function () {
  const items = this.querySelectorAll('.todo-list li');
  items.forEach(item => {
    expect(item.classList.contains('completed')).to.be.false;
  });
});

Then('the toggle-all checkbox is checked', function () {
  const toggleAll = this.querySelector('#toggle-all');
  expect(toggleAll.checked).to.be.true;
});

Then('the toggle-all checkbox is not checked', function () {
  const toggleAll = this.querySelector('#toggle-all');
  expect(toggleAll.checked).to.be.false;
});

// Editing
When('the user double-clicks the first todo label', function () {
  const label = this.querySelector('.todo-list li:first-child label');
  label.dispatchEvent(new this.window.Event('dblclick'));
});

Then('the first todo edit input has value {string}', function (value) {
  const editInput = this.querySelector('.todo-list li:first-child .edit');
  expect(editInput).to.not.be.null;
  expect(editInput.value).to.equal(value);
});

Then('the first todo edit input is focused', function () {
  const editInput = this.querySelector('.todo-list li:first-child .edit');
  expect(editInput).to.not.be.null;
  expect(this.document.activeElement).to.equal(editInput);
});

When('the first todo edit input is changed to {string}', function (value) {
  const editInput = this.querySelector('.todo-list li:first-child .edit');
  editInput.value = value;
  editInput.dispatchEvent(new this.window.Event('input'));
});

When('the user presses Enter on the edit input', function () {
  const editInput = this.querySelector('.todo-list li:first-child .edit');
  editInput.dispatchEvent(new this.window.KeyboardEvent('keydown', { key: 'Enter', keyCode: 13 }));
});

When('the edit input loses focus', function () {
  const editInput = this.querySelector('.todo-list li:first-child .edit');
  editInput.dispatchEvent(new this.window.Event('blur'));
});

Then('the first todo does not have class {string}', function (className) {
  const firstTodo = this.querySelector('.todo-list li');
  expect(firstTodo).to.not.be.null;
  expect(firstTodo.classList.contains(className)).to.be.false;
});

When('the user presses Escape on the edit input', function () {
  const editInput = this.querySelector('.todo-list li:first-child .edit');
  editInput.dispatchEvent(new this.window.KeyboardEvent('keydown', { key: 'Escape', keyCode: 27 }));
});

// Deleting
When('the user clicks the first todo destroy button', function () {
  const destroyBtn = this.querySelector('.todo-list li:first-child .destroy');
  destroyBtn.click();
});

// Clear completed
When('the user clicks the clear-completed button', function () {
  const clearBtn = this.querySelector('.clear-completed');
  clearBtn.click();
});

// Visibility
Then('the main section is hidden', function () {
  const main = this.querySelector('.main');
  expect(main).to.not.be.null;
  expect(main.style.display === 'none' || main.classList.contains('hidden')).to.be.true;
});

Then('the footer section is hidden', function () {
  const footer = this.querySelector('.footer');
  expect(footer).to.not.be.null;
  expect(footer.style.display === 'none' || footer.classList.contains('hidden')).to.be.true;
});

Then('the main section is visible', function () {
  const main = this.querySelector('.main');
  expect(main).to.not.be.null;
  expect(main.style.display !== 'none').to.be.true;
});

Then('the footer section is visible', function () {
  const footer = this.querySelector('.footer');
  expect(footer).to.not.be.null;
  expect(footer.style.display !== 'none').to.be.true;
});

// Counter
Then('the counter text is {string}', function (text) {
  const counter = this.querySelector('.todo-count');
  expect(counter).to.not.be.null;
  expect(counter.textContent.trim()).to.equal(text);
});

// Clear completed visibility
Then('the clear-completed button is hidden', function () {
  const btn = this.querySelector('.clear-completed');
  expect(btn).to.not.be.null;
  expect(btn.style.display === 'none' || btn.classList.contains('hidden')).to.be.true;
});

Then('the clear-completed button is visible', function () {
  const btn = this.querySelector('.clear-completed');
  expect(btn).to.not.be.null;
  expect(btn.style.display !== 'none').to.be.true;
});

// Routing
When('the route is {string}', function (route) {
  this.window.location.hash = route;
});

Then('the todo list shows {int} item(s)', function (count) {
  const items = this.querySelectorAll('.todo-list li');
  expect(items.length).to.equal(count);
});

Then('the filter link {string} is selected', function (linkText) {
  const links = this.querySelectorAll('.filters a');
  let found = false;
  links.forEach(link => {
    if (link.textContent === linkText) {
      expect(link.classList.contains('selected')).to.be.true;
      found = true;
    }
  });
  expect(found).to.be.true;
});

Then('the filter link {string} is not selected', function (linkText) {
  const links = this.querySelectorAll('.filters a');
  links.forEach(link => {
    if (link.textContent === linkText) {
      expect(link.classList.contains('selected')).to.be.false;
    }
  });
});

// Persistence
When('the page is reloaded', function () {
  // Save current state
  const todos = this.localStorage.getItem('todos-todomvc');
  const hash = this.window.location.hash;

  // Reload by re-creating window
  this.loadApp();

  // Restore state
  if (todos) {
    this.localStorage.setItem('todos-todomvc', todos);
  }
  this.window.location.hash = hash;

  // Trigger DOMContentLoaded again
  this.document.dispatchEvent(new this.window.Event('DOMContentLoaded'));
});

Then('localStorage contains a key {string}', function (key) {
  expect(this.localStorage.getItem(key)).to.not.be.null;
});

Then('localStorage[{string}] is a JSON array', function (key) {
  const value = this.localStorage.getItem(key);
  expect(value).to.not.be.null;
  const parsed = JSON.parse(value);
  expect(Array.isArray(parsed)).to.be.true;
});

Then('each todo has keys {string}, {string}, {string}', function (key1, key2, key3) {
  const value = this.localStorage.getItem('todos-todomvc');
  const parsed = JSON.parse(value);
  parsed.forEach(todo => {
    expect(todo).to.have.property(key1);
    expect(todo).to.have.property(key2);
    expect(todo).to.have.property(key3);
  });
});

/**
 * TodoMVC App
 * Vanilla JavaScript implementation
 */
(function () {
  'use strict';

  // Constants
  var ENTER_KEY = 13;
  var ESCAPE_KEY = 27;
  var STORAGE_KEY = 'todos-todomvc';

  // DOM elements
  var newTodoInput = document.querySelector('.new-todo');
  var todoList = document.querySelector('.todo-list');
  var toggleAll = document.querySelector('#toggle-all');
  var todoCount = document.querySelector('.todo-count');
  var clearCompleted = document.querySelector('.clear-completed');
  var main = document.querySelector('.main');
  var footer = document.querySelector('.footer');
  var filters = document.querySelectorAll('.filters a');

  // State
  var todos = [];
  var currentFilter = 'all';

  // Generate unique ID
  function generateId() {
    return Date.now().toString(36) + Math.random().toString(36).substr(2);
  }

  // Load todos from localStorage
  function loadTodos() {
    try {
      var stored = localStorage.getItem(STORAGE_KEY);
      if (stored) {
        todos = JSON.parse(stored);
      }
    } catch (e) {
      todos = [];
    }
  }

  // Save todos to localStorage
  function saveTodos() {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(todos));
  }

  // Render the todo list
  function render() {
    // Clear existing items
    todoList.innerHTML = '';

    // Filter todos based on current route
    var filteredTodos = todos.filter(function (todo) {
      if (currentFilter === 'active') {
        return !todo.completed;
      }
      if (currentFilter === 'completed') {
        return todo.completed;
      }
      return true;
    });

    // Render each todo
    filteredTodos.forEach(function (todo) {
      var li = document.createElement('li');
      li.dataset.id = todo.id;
      if (todo.completed) {
        li.classList.add('completed');
      }

      li.innerHTML =
        '<div class="view">' +
          '<input class="toggle" type="checkbox"' + (todo.completed ? ' checked' : '') + '>' +
          '<label>' + escapeHtml(todo.title) + '</label>' +
          '<button class="destroy"></button>' +
        '</div>' +
        '<input class="edit" value="' + escapeHtml(todo.title) + '">';

      todoList.appendChild(li);
    });

    // Update counter
    var activeCount = todos.filter(function (todo) {
      return !todo.completed;
    }).length;
    var itemCount = activeCount === 1 ? 'item' : 'items';
    todoCount.innerHTML = '<strong>' + activeCount + '</strong> ' + itemCount + ' left';

    // Update main and footer visibility
    if (todos.length === 0) {
      main.style.display = 'none';
      footer.style.display = 'none';
    } else {
      main.style.display = '';
      footer.style.display = '';
    }

    // Update toggle-all state
    toggleAll.checked = todos.length > 0 && todos.every(function (todo) {
      return todo.completed;
    });

    // Update clear completed visibility
    var hasCompleted = todos.some(function (todo) {
      return todo.completed;
    });
    clearCompleted.style.display = hasCompleted ? '' : 'none';

    // Update filter links
    filters.forEach(function (link) {
      var filter = link.getAttribute('href').replace('#/', '');
      if (filter === '') {
        filter = 'all';
      }
      if (filter === currentFilter) {
        link.classList.add('selected');
      } else {
        link.classList.remove('selected');
      }
    });
  }

  // Escape HTML to prevent XSS
  function escapeHtml(text) {
    var div = document.createElement('div');
    div.textContent = text;
    return div.innerHTML;
  }

  // Add a new todo
  function addTodo(title) {
    title = title.trim();
    if (title === '') {
      return;
    }
    todos.push({
      id: generateId(),
      title: title,
      completed: false
    });
    saveTodos();
    render();
  }

  // Toggle a todo's completed state
  function toggleTodo(id) {
    todos.forEach(function (todo) {
      if (todo.id === id) {
        todo.completed = !todo.completed;
      }
    });
    saveTodos();
    render();
  }

  // Toggle all todos
  function toggleAllTodos() {
    var allCompleted = todos.every(function (todo) {
      return todo.completed;
    });
    todos.forEach(function (todo) {
      todo.completed = !allCompleted;
    });
    saveTodos();
    render();
  }

  // Delete a todo
  function deleteTodo(id) {
    todos = todos.filter(function (todo) {
      return todo.id !== id;
    });
    saveTodos();
    render();
  }

  // Edit a todo
  function editTodo(id, newTitle) {
    newTitle = newTitle.trim();
    if (newTitle === '') {
      deleteTodo(id);
      return;
    }
    todos.forEach(function (todo) {
      if (todo.id === id) {
        todo.title = newTitle;
      }
    });
    saveTodos();
    render();
  }

  // Clear completed todos
  function clearCompletedTodos() {
    todos = todos.filter(function (todo) {
      return !todo.completed;
    });
    saveTodos();
    render();
  }

  // Enter editing mode
  function enterEditMode(li) {
    li.classList.add('editing');
    var editInput = li.querySelector('.edit');
    editInput.focus();
  }

  // Exit editing mode
  function exitEditMode(li) {
    li.classList.remove('editing');
  }

  // Get todo ID from list item
  function getTodoId(li) {
    return li.dataset.id;
  }

  // Event: New todo input
  newTodoInput.addEventListener('keydown', function (e) {
    if (e.keyCode === ENTER_KEY) {
      addTodo(newTodoInput.value);
      newTodoInput.value = '';
    }
  });

  // Event: Toggle all
  toggleAll.addEventListener('change', function () {
    toggleAllTodos();
  });

  // Event: Clear completed
  clearCompleted.addEventListener('click', function () {
    clearCompletedTodos();
  });

  // Event: Todo list interactions (delegated)
  todoList.addEventListener('click', function (e) {
    var target = e.target;
    var li = target.closest('li');
    if (!li) return;

    var id = getTodoId(li);

    // Toggle checkbox
    if (target.classList.contains('toggle')) {
      toggleTodo(id);
      return;
    }

    // Delete button
    if (target.classList.contains('destroy')) {
      deleteTodo(id);
      return;
    }
  });

  // Event: Double-click to edit
  todoList.addEventListener('dblclick', function (e) {
    var target = e.target;
    if (target.tagName === 'LABEL') {
      var li = target.closest('li');
      if (li) {
        enterEditMode(li);
      }
    }
  });

  // Event: Edit input keydown
  todoList.addEventListener('keydown', function (e) {
    var target = e.target;
    if (!target.classList.contains('edit')) return;

    var li = target.closest('li');
    if (!li) return;

    var id = getTodoId(li);

    if (e.keyCode === ENTER_KEY) {
      editTodo(id, target.value);
      exitEditMode(li);
    } else if (e.keyCode === ESCAPE_KEY) {
      target.value = li.querySelector('label').textContent;
      exitEditMode(li);
    }
  });

  // Event: Edit input blur
  todoList.addEventListener('blur', function (e) {
    var target = e.target;
    if (!target.classList.contains('edit')) return;

    var li = target.closest('li');
    if (!li) return;

    var id = getTodoId(li);
    editTodo(id, target.value);
    exitEditMode(li);
  }, true);

  // Event: Filter links
  filters.forEach(function (link) {
    link.addEventListener('click', function (e) {
      e.preventDefault();
      var hash = link.getAttribute('href');
      window.location.hash = hash;
    });
  });

  // Route handling
  function handleRoute() {
    var hash = window.location.hash || '#/';
    if (hash === '#/' || hash === '#') {
      currentFilter = 'all';
    } else if (hash === '#/active') {
      currentFilter = 'active';
    } else if (hash === '#/completed') {
      currentFilter = 'completed';
    }
    render();
  }

  window.addEventListener('hashchange', handleRoute);

  // Initialize
  function init() {
    loadTodos();
    handleRoute();
  }

  // Start app when DOM is ready
  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', init);
  } else {
    init();
  }
})();

