const { World, Before, After, setWorldConstructor } = require('@cucumber/cucumber');
const { Window } = require('happy-dom');
const fs = require('fs');
const path = require('path');

class AppWorld extends World {
  constructor(options) {
    super(options);
    this.window = null;
    this.document = null;
    this.localStorage = null;
  }

  loadApp() {
    const htmlPath = path.resolve(__dirname, '../../assets/app-template.index.html');
    let html = fs.readFileSync(htmlPath, 'utf8');

    // Fix paths for test environment
    html = html.replace('node_modules/todomvc-common/base.css', '../../node_modules/todomvc-common/base.css');
    html = html.replace('node_modules/todomvc-app-css/index.css', '../../node_modules/todomvc-app-css/index.css');
    html = html.replace('css/app.css', '../../css/app.css');
    html = html.replace('node_modules/todomvc-common/base.js', '../../node_modules/todomvc-common/base.js');
    html = html.replace('js/app.js', '../../js/app.js');

    this.window = new Window({
      url: 'http://localhost',
      contentType: 'text/html',
    });
    this.document = this.window.document;
    this.localStorage = this.window.localStorage;

    // Write HTML to window
    this.document.open();
    this.document.write(html);
    this.document.close();

    // Load the app script
    const appPath = path.resolve(__dirname, '../../js/app.js');
    if (fs.existsSync(appPath)) {
      const appScript = fs.readFileSync(appPath, 'utf8');
      const scriptEl = this.document.createElement('script');
      scriptEl.textContent = appScript;
      this.document.body.appendChild(scriptEl);
    }
  }

  createElement(tag, attrs = {}) {
    const el = this.document.createElement(tag);
    for (const [key, value] of Object.entries(attrs)) {
      el.setAttribute(key, value);
    }
    return el;
  }

  querySelector(selector) {
    return this.document.querySelector(selector);
  }

  querySelectorAll(selector) {
    return this.document.querySelectorAll(selector);
  }
}

setWorldConstructor(AppWorld);

