/**
 * TodoMVC App
 * Vanilla JavaScript implementation
 */
(function () {
  'use strict';

  // Constants
  var ENTER_KEY = 13;
  var ESCAPE_KEY = 27;
  var STORAGE_KEY = 'todos-todomvc';

  // DOM elements
  var newTodoInput = document.querySelector('.new-todo');
  var todoList = document.querySelector('.todo-list');
  var toggleAll = document.querySelector('#toggle-all');
  var todoCount = document.querySelector('.todo-count');
  var clearCompleted = document.querySelector('.clear-completed');
  var main = document.querySelector('.main');
  var footer = document.querySelector('.footer');
  var filters = document.querySelectorAll('.filters a');

  // State
  var todos = [];
  var currentFilter = 'all';

  // Generate unique ID
  function generateId() {
    return Date.now().toString(36) + Math.random().toString(36).substr(2);
  }

  // Load todos from localStorage
  function loadTodos() {
    try {
      var stored = localStorage.getItem(STORAGE_KEY);
      if (stored) {
        todos = JSON.parse(stored);
      }
    } catch (e) {
      todos = [];
    }
  }

  // Save todos to localStorage
  function saveTodos() {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(todos));
  }

  // Render the todo list
  function render() {
    // Clear existing items
    todoList.innerHTML = '';

    // Filter todos based on current route
    var filteredTodos = todos.filter(function (todo) {
      if (currentFilter === 'active') {
        return !todo.completed;
      }
      if (currentFilter === 'completed') {
        return todo.completed;
      }
      return true;
    });

    // Render each todo
    filteredTodos.forEach(function (todo) {
      var li = document.createElement('li');
      li.dataset.id = todo.id;
      if (todo.completed) {
        li.classList.add('completed');
      }

      li.innerHTML =
        '<div class="view">' +
          '<input class="toggle" type="checkbox"' + (todo.completed ? ' checked' : '') + '>' +
          '<label>' + escapeHtml(todo.title) + '</label>' +
          '<button class="destroy"></button>' +
        '</div>' +
        '<input class="edit" value="' + escapeHtml(todo.title) + '">';

      todoList.appendChild(li);
    });

    // Update counter
    var activeCount = todos.filter(function (todo) {
      return !todo.completed;
    }).length;
    var itemCount = activeCount === 1 ? 'item' : 'items';
    todoCount.innerHTML = '<strong>' + activeCount + '</strong> ' + itemCount + ' left';

    // Update main and footer visibility
    if (todos.length === 0) {
      main.style.display = 'none';
      footer.style.display = 'none';
    } else {
      main.style.display = '';
      footer.style.display = '';
    }

    // Update toggle-all state
    toggleAll.checked = todos.length > 0 && todos.every(function (todo) {
      return todo.completed;
    });

    // Update clear completed visibility
    var hasCompleted = todos.some(function (todo) {
      return todo.completed;
    });
    clearCompleted.style.display = hasCompleted ? '' : 'none';

    // Update filter links
    filters.forEach(function (link) {
      var filter = link.getAttribute('href').replace('#/', '');
      if (filter === '') {
        filter = 'all';
      }
      if (filter === currentFilter) {
        link.classList.add('selected');
      } else {
        link.classList.remove('selected');
      }
    });
  }

  // Escape HTML to prevent XSS
  function escapeHtml(text) {
    var div = document.createElement('div');
    div.textContent = text;
    return div.innerHTML;
  }

  // Add a new todo
  function addTodo(title) {
    title = title.trim();
    if (title === '') {
      return;
    }
    todos.push({
      id: generateId(),
      title: title,
      completed: false
    });
    saveTodos();
    render();
  }

  // Toggle a todo's completed state
  function toggleTodo(id) {
    todos.forEach(function (todo) {
      if (todo.id === id) {
        todo.completed = !todo.completed;
      }
    });
    saveTodos();
    render();
  }

  // Toggle all todos
  function toggleAllTodos() {
    var allCompleted = todos.every(function (todo) {
      return todo.completed;
    });
    todos.forEach(function (todo) {
      todo.completed = !allCompleted;
    });
    saveTodos();
    render();
  }

  // Delete a todo
  function deleteTodo(id) {
    todos = todos.filter(function (todo) {
      return todo.id !== id;
    });
    saveTodos();
    render();
  }

  // Edit a todo
  function editTodo(id, newTitle) {
    newTitle = newTitle.trim();
    if (newTitle === '') {
      deleteTodo(id);
      return;
    }
    todos.forEach(function (todo) {
      if (todo.id === id) {
        todo.title = newTitle;
      }
    });
    saveTodos();
    render();
  }

  // Clear completed todos
  function clearCompletedTodos() {
    todos = todos.filter(function (todo) {
      return !todo.completed;
    });
    saveTodos();
    render();
  }

  // Enter editing mode
  function enterEditMode(li) {
    li.classList.add('editing');
    var editInput = li.querySelector('.edit');
    editInput.focus();
  }

  // Exit editing mode
  function exitEditMode(li) {
    li.classList.remove('editing');
  }

  // Get todo ID from list item
  function getTodoId(li) {
    return li.dataset.id;
  }

  // Event: New todo input
  newTodoInput.addEventListener('keydown', function (e) {
    if (e.keyCode === ENTER_KEY) {
      addTodo(newTodoInput.value);
      newTodoInput.value = '';
    }
  });

  // Event: Toggle all
  toggleAll.addEventListener('change', function () {
    toggleAllTodos();
  });

  // Event: Clear completed
  clearCompleted.addEventListener('click', function () {
    clearCompletedTodos();
  });

  // Event: Todo list interactions (delegated)
  todoList.addEventListener('click', function (e) {
    var target = e.target;
    var li = target.closest('li');
    if (!li) return;

    var id = getTodoId(li);

    // Toggle checkbox
    if (target.classList.contains('toggle')) {
      toggleTodo(id);
      return;
    }

    // Delete button
    if (target.classList.contains('destroy')) {
      deleteTodo(id);
      return;
    }
  });

  // Event: Double-click to edit
  todoList.addEventListener('dblclick', function (e) {
    var target = e.target;
    if (target.tagName === 'LABEL') {
      var li = target.closest('li');
      if (li) {
        enterEditMode(li);
      }
    }
  });

  // Event: Edit input keydown
  todoList.addEventListener('keydown', function (e) {
    var target = e.target;
    if (!target.classList.contains('edit')) return;

    var li = target.closest('li');
    if (!li) return;

    var id = getTodoId(li);

    if (e.keyCode === ENTER_KEY) {
      editTodo(id, target.value);
      exitEditMode(li);
    } else if (e.keyCode === ESCAPE_KEY) {
      target.value = li.querySelector('label').textContent;
      exitEditMode(li);
    }
  });

  // Event: Edit input blur
  todoList.addEventListener('blur', function (e) {
    var target = e.target;
    if (!target.classList.contains('edit')) return;

    var li = target.closest('li');
    if (!li) return;

    var id = getTodoId(li);
    editTodo(id, target.value);
    exitEditMode(li);
  }, true);

  // Event: Filter links
  filters.forEach(function (link) {
    link.addEventListener('click', function (e) {
      e.preventDefault();
      var hash = link.getAttribute('href');
      window.location.hash = hash;
    });
  });

  // Route handling
  function handleRoute() {
    var hash = window.location.hash || '#/';
    if (hash === '#/' || hash === '#') {
      currentFilter = 'all';
    } else if (hash === '#/active') {
      currentFilter = 'active';
    } else if (hash === '#/completed') {
      currentFilter = 'completed';
    }
    render();
  }

  window.addEventListener('hashchange', handleRoute);

  // Initialize
  function init() {
    // Clear any sample todos from template
    todoList.innerHTML = '';
    loadTodos();
    handleRoute();
  }

  // Start app when DOM is ready
  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', init);
  } else {
    init();
  }
})();

